If.CustomBehavior:
// Sample of how to use Zeppelin/Ship
// In this sample, WRobot catch Zeppelin from Kalimdor (Ogrimmard) to Northrend (Borean Tundra (Warsong Hold))

/* Quest settings:
    * Can condition: "return Usefuls.ContinentId == (int) ContinentId.Azeroth;"
    * Is complete condition: "return Usefuls.ContinentId == (int) ContinentId.Northrend && !Me.InTransport;"
    * Not required in quest log: "True"
    * Quest type: "OverridePulseCSharpCode"
*/

// You can get zeppelin/ship/player positions and entry ID in tab "Tools" > "Development Tools" > "Dump all informations" (or "Memory information").

// Settings:
var zeppelinEntryId = 190536; // Zeppelin/Ship EntryId
// From
var fromZeppelinWaitPosition = new WoWPoint(-8288.816, 1424.703, -0.0459401); // Position where Zeppelin/Ship waits players (from)
var fromPlayerWaitPosition = new WoWPoint(-8291.715f, 1403.649f, 4.727906f); // Position where the player waits Zeppelin/Ship (from)
var fromPlayerInZeppelinPosition = new WoWPoint(-8292.988f, 1423.243f, 9.438203f); // Position where the player waits in the Zeppelin/Ship (from)
// To
var toZeppelinWaitPosition = new WoWPoint(2218.391, 5119.588, -0.02230995); // Position where Zeppelin/Ship waits players (to)
var toPlayerLeavePosition = new WoWPoint(2233.704f, 5137.47f, 5.343467f); // Position to go out the Zeppelin/Ship (to)

// Change WRobot settings:
wManager.wManagerSetting.CurrentSetting.CloseIfPlayerTeleported = false;

// Code:
if (!Conditions.InGameAndConnectedAndProductStartedNotInPause)
    return true;

if (Usefuls.ContinentId == (int)ContinentId.Azeroth)
{
    if (!Me.InTransport)
    {
        if (GoToTask.ToPosition(fromPlayerWaitPosition))
        {
            var zeppelin = ObjectManager.GetWoWGameObjectByEntry(zeppelinEntryId).OrderBy(o => o.GetDistance).FirstOrDefault();
            if (zeppelin != null && zeppelin.Position.DistanceTo(fromZeppelinWaitPosition) < 1)
            {
                GoToTask.ToPosition(fromPlayerInZeppelinPosition);
            }
        }
    }
}
else if (Usefuls.ContinentId == (int)ContinentId.Northrend)
{
    if (Me.InTransport)
    {
        var zeppelin = ObjectManager.GetWoWGameObjectByEntry(zeppelinEntryId).OrderBy(o => o.GetDistance).FirstOrDefault();
        if (zeppelin != null && zeppelin.Position.DistanceTo(toZeppelinWaitPosition) < 1)
        {
            GoToTask.ToPosition(toPlayerLeavePosition);
        }
    }
}
return true;

Thread t = System.Threading.Tasks.Task.Run(async () =>
{
    int itemId = 35278;
    int questId = 11889;

    while (TreeRoot.IsRunning)
    {
        if (Me.IsAlive && Me.IsAutoRunning)
        {
            if (!Quest.HasQuest(questId))
                break;

            WoWUnit target = Me.CurrentTarget;

            if (target != null && target.IsValid && target.IsAlive && target.IsAttackable && !Me.InCombat)
            {
                UseItem(itemId);
                await Coroutine.Sleep(1000); // Ждём 1 секунду между использованием
            }
            else
            {
                await Coroutine.Sleep(500); // Если нет цели или в бою — короткая пауза
            }
        }
        else
        {
            await Coroutine.Sleep(1000); // Если бот не активен или в паузе — подождать
        }
    }
});

