        if (!Quest.HasQuest(questId) || Quest.IsObjectiveComplete(1, questId))
            break;

        // Ищем ближайшего мертвого NPC
        var npc = ObjectManager.GetWoWUnitByEntry(npcEntry)
            .Where(u => u.IsValid && !u.IsAlive)
