    if (Me.Position.DistanceTo(patrolPoint) < 5f)
    {
        patrolIndex = (patrolIndex + 1) % HotSpots.Count;
        currentTargetPosition = WoWPoint.Empty;
    }

    await Coroutine.Sleep(500);
}

return true;

Thread t = System.Threading.Tasks.Task.Run(async () =>
{
    int questId = 11396;
    int npcEntry = 24464;
    int itemId = 33960;

    while (TreeRoot.IsRunning)
    {
        if (!Me.IsAlive && Me.IsAutoRunning)
        {
            await Coroutine.Sleep(500);
            continue;
        }

        if (!Quest.HasQuest(questId) || Quest.IsObjectiveComplete(1, questId))
            break;

        var npc = ObjectManager.GetWoWUnitByEntry(npcEntry)
            .Where(u => u.IsValid && u.IsAlive)
            .OrderBy(u => u.GetDistance)
            .FirstOrDefault();

        if (npc != null)
        {
            if (npc.GetDistance > 5)
                wManager.Wow.Bot.Tasks.GoToTask.ToPosition(npc.Position, 4f);

            Lua.DoString("/targetexact " + npc.Name);
            await Coroutine.Sleep(300);

            if (GetItemCountByIdLUA(itemId) >= 1)
            {
                UseItem(itemId);

                // ⏳ Ждём окончания каста (макс 8 сек)
                int timeout = 8000;
                int waited = 0;
                while (Me.IsCast && waited < timeout)
                {
                    await Coroutine.Sleep(200);
                    waited += 200;
                }

                await Coroutine.Sleep(1000); // Небольшая пауза

                // ✅ Атакуем, если цель всё ещё жива
                var currentTarget = Me.CurrentTarget;
                if (currentTarget.IsValid && currentTarget.IsAlive && currentTarget.Entry == npcEntry)
                {
                    Fight.StartFight(currentTarget.Guid);
                    while (Me.InCombat && currentTarget.IsValid)
                        await Coroutine.Sleep(500);
                }
            }
        }

        await Coroutine.Sleep(500);
    }
});

