Thread t = System.Threading.Tasks.Task.Run(async () =>
{
    int deathboltId = 51854;
    int freyaTalismanItemId = 38657;

    while (TreeRoot.IsRunning)
    {
        if (Me.IsAlive && Me.IsAutoRunning)
        {
            var target = Me.CurrentTarget;

            if (target != null && target.IsValid && target.IsAlive && target.IsCast && target.CastingSpellId == deathboltId)
            {
                // Прерываем бой
                Me.ClearTarget();

                // Используем Оберег Фрейи
                UseItem(freyaTalismanItemId);

                // Ждём, пока моб закончит каст или максимум 6 секунд (защита от бесконечного каста)
                int waitTimeMs = 0;
                while (target.IsCast && target.CastingSpellId == deathboltId && waitTimeMs < 6000)
                {
                    await Coroutine.Sleep(200);
                    waitTimeMs += 200;
                }

                // Подождать ещё немного перед возобновлением боя
                await Coroutine.Sleep(500);
            }
        }

        await Coroutine.Sleep(100); // Частая проверка
    }
});

if (!Quest.HasQuest(12805))
    return false;

int itemId = 40397;
int questId = 12805;
int targetEntry = 29124;

List<WoWPoint> HotSpots = new List<WoWPoint>
{
    new WoWPoint(5719.361f, 3931.569f, -76.36964f),
    new WoWPoint(5498.905f, 3965.495f, -51.54444f),
    new WoWPoint(5638.905f, 3668.731f, -26.11596f)
};

int patrolIndex = 0;
WoWPoint currentTargetPosition = WoWPoint.Empty;

while (TreeRoot.IsRunning)
{
    if (!Me.IsAlive && Me.IsAutoRunning)
    {
        await Coroutine.Sleep(500);
        continue;
    }

    // Выход при выполнении цели
    if (Quest.IsObjectiveComplete(1, questId))
        break;

    // Поиск цели
    var target = ObjectManager.GetObjectWoWUnit()
        .Where(u => u.IsAlive && u.Entry == targetEntry && u.GetDistance <= 60)
        .OrderBy(u => u.GetDistance)
        .FirstOrDefault();

    if (target != null)
    {
        Lua.DoString("/targetexact " + target.Name);
        await Coroutine.Sleep(300);

        var currentTarget = Me.CurrentTarget;

        if (currentTarget.IsValid && currentTarget.IsAlive && currentTarget.Entry == targetEntry)
        {
            Logging.Write("Начинаем бой с целью: " + currentTarget.Name);
            Fight.StartFight(currentTarget.Guid);
            await Coroutine.Sleep(1000);

            while (Me.InCombat && currentTarget.IsValid)
                await Coroutine.Sleep(500);

            Lua.DoString("/TargetLastEnemy");
            await Coroutine.Sleep(300);

            currentTarget = Me.CurrentTarget;

            if (currentTarget.IsValid && currentTarget.IsDead && currentTarget.Entry == targetEntry)
            {
                Logging.Write("Цель мертва, применяем предмет.");
                UseItem(itemId);
                await Coroutine.Sleep(5000);
            }

            continue;
        }
    }

    // Патрулирование без рывков
    var patrolPoint = HotSpots[patrolIndex];

    // Если он не идёт или точка изменилась - начать движение
    if (!MovementManager.InMovement || currentTargetPosition != patrolPoint)
    {
        Logging.Write("Двигаемся к точке патруля: " + patrolPoint);
        currentTargetPosition = patrolPoint;
        wManager.Wow.Bot.Tasks.GoToTask.ToPosition(patrolPoint, 5f);
    }

    // Если подошёл к точке - сменить её
    if (Me.Position.DistanceTo(patrolPoint) < 5f)
    {
        patrolIndex = (patrolIndex + 1) % HotSpots.Count;
        currentTargetPosition = WoWPoint.Empty;
    }

    await Coroutine.Sleep(500);
}

return true;

